const BINARIOS = {"docs/capturas/33-calidad.png": ""}

let avisos = 0
const leer = (p) => fs.readFileSync(p, 'utf8')
const crlf = (s) => s.includes('\r\n')
const guardar = (p, texto, conCrlf) => fs.writeFileSync(p, conCrlf ? texto.replace(/\r?\n/g, '\r\n') : texto)

if (!fs.existsSync('README.md') || !fs.existsSync('docs') || !fs.existsSync('database')) {
  console.error('✗ Ejecútalo desde la carpeta raíz del proyecto (donde están README.md, docs y database).'); process.exit(1)
}

// CHANGELOG: la 0.57.0 encima de la 0.56.0
{
  const raw = leer('CHANGELOG.md'), c = crlf(raw)
  let s = raw.replace(/\r\n/g, '\n')
  if (s.includes('## [0.57.0]')) console.log('· CHANGELOG ya tenía la 0.57.0')
  else if (!s.includes('## [0.56.0]')) { avisos++; console.log('⚠ CHANGELOG.md: no encuentro "## [0.56.0]"') }
  else { s = s.replace('## [0.56.0]', CHANGELOG + '## [0.56.0]'); guardar('CHANGELOG.md', s, c); console.log('✓ CHANGELOG.md: 0.57.0') }
}

// Bitácora, al final
{
  const raw = leer('docs/bitacora.md'), c = crlf(raw)
  let s = raw.replace(/\r\n/g, '\n')
  if (s.includes('· v0.57.0 ·')) console.log('· La bitácora ya tenía la v0.57.0')
  else { s = s.replace(/\n*$/, '\n\n') + BITACORA; guardar('docs/bitacora.md', s, c); console.log('✓ docs/bitacora.md: v0.57.0') }
}

// README
{
  const raw = leer('README.md'), c = crlf(raw)
  let s = raw.replace(/\r\n/g, '\n')
  for (const [de, a] of README) {
    if (s.includes(a)) continue
    if (!s.includes(de)) { avisos++; console.log('⚠ README.md: no encuentro «' + de.trim().slice(0, 70) + '»'); continue }
    s = s.replace(de, a)
  }
  guardar('README.md', s, c); console.log('✓ README.md')
}

// Versión de la web
{
  const p = 'frontend/package.json'
  const s = leer(p)
  if (s.includes('"version": "0.57.0"')) console.log('· package.json ya estaba en 0.57.0')
  else if (s.includes('"version": "0.56.0"')) { fs.writeFileSync(p, s.replace('"version": "0.56.0"', '"version": "0.57.0"')); console.log('✓ frontend/package.json: 0.57.0') }
  else { avisos++; console.log('⚠ frontend/package.json: no encuentro la versión 0.56.0') }
}

// ADR, captura, volcado de funciones y diagnóstico de Supabase
let n = 0
for (const [p, texto] of Object.entries(FICHEROS)) {
  const actual = fs.existsSync(p) ? leer(p) : null
  if (actual !== null && actual.replace(/\r\n/g, '\n') === texto) continue
  fs.mkdirSync(path.dirname(p), { recursive: true })
  guardar(p, texto, actual !== null && crlf(actual)); n++
}
for (const [p, b64] of Object.entries(BINARIOS)) {
  const buf = Buffer.from(b64, 'base64')
  if (fs.existsSync(p) && fs.readFileSync(p).equals(buf)) continue
  fs.mkdirSync(path.dirname(p), { recursive: true }); fs.writeFileSync(p, buf); n++
}
console.log(n ? `✓ ADR, captura, volcado y diagnóstico: ${n} fichero(s) al día` : '· ADR, captura, volcado y diagnóstico ya estaban al día')

console.log(avisos ? `\nHecho con ${avisos} aviso(s): pásame el mensaje y lo vemos.` : '\n✔ Paso 281 aplicado. Revisa: git --no-pager diff --stat')
